-- READ-ONLY verification for 2027-01-18_customer_retention.sql. Run AFTER applying it. Every row should say ok = true.
select 'the four tables exist and are ours' as check_name, (select count(*) from unnest(array['promotions', 'promotion_deliveries', 'promotion_redemptions', 'profile_reviews']) t where coalesce(obj_description(to_regclass('public.' || t), 'pg_class'), '') = 'managed by 2027-01-18_customer_retention.sql') = 4 as ok;
select 'row-level security is on with no policy' as check_name, (select count(*) from unnest(array['promotions', 'promotion_deliveries', 'promotion_redemptions', 'profile_reviews']) t where (select relrowsecurity from pg_class where oid = to_regclass('public.' || t)) and not exists (select 1 from pg_policy where polrelid = to_regclass('public.' || t))) = 4 as ok;
select 'no API role can reach any of them' as check_name, not exists (select 1 from unnest(array['promotions', 'promotion_deliveries', 'promotion_redemptions', 'profile_reviews']) t, unnest(array['anon', 'authenticated']) r where has_any_column_privilege(r, 'public.' || t, 'select') or has_any_column_privilege(r, 'public.' || t, 'insert') or has_any_column_privilege(r, 'public.' || t, 'update') or has_table_privilege(r, 'public.' || t, 'delete')) as ok;
select 'deliveries and redemptions are append-only for the service role' as check_name, not (has_table_privilege('service_role', 'public.promotion_deliveries', 'update') or has_table_privilege('service_role', 'public.promotion_deliveries', 'delete') or has_table_privilege('service_role', 'public.promotion_redemptions', 'update') or has_table_privilege('service_role', 'public.promotion_redemptions', 'delete')) as ok;
select 'the four functions are callable by the service role only' as check_name, (select count(*) from unnest(array['customer_segments(uuid, uuid)', 'customer_has_interaction(uuid, uuid)', 'promotion_redeem(uuid, uuid, uuid, uuid, integer, text)', 'review_save(uuid, uuid, integer, text)']) f where has_function_privilege('service_role', 'public.' || f, 'execute') and not has_function_privilege('anon', 'public.' || f, 'execute') and not has_function_privilege('authenticated', 'public.' || f, 'execute')) = 4 as ok;
select 'a church or ministry cannot be reviewed (the function refuses it)' as check_name, pg_get_functiondef('public.review_save(uuid, uuid, integer, text)'::regprocedure) like '%church_ministries%' as ok;
-- informational: a new migration starts empty
select (select count(*) from public.promotions) as promotions, (select count(*) from public.promotion_deliveries) as deliveries, (select count(*) from public.promotion_redemptions) as redemptions, (select count(*) from public.profile_reviews) as reviews;
